def brackets_balanced(s: str) -> bool:
    stack = []
    matching = {")": "(", "]": "[", "}": "{"}
    opening = set(matching.values())
    in_string = False
    i = 0

    while i < len(s):
        char = s[i]

        if in_string:
            if char == "\\":
                if i + 1 < len(s) and s[i + 1] in {'"', "\\"}:
                    i += 2
                    continue
            elif char == '"':
                in_string = False
            i += 1
            continue

        if char == '"':
            in_string = True
        elif char in opening:
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False

        i += 1

    return not in_string and not stack
